#!/usr/bin/env python3
"""Non-conforming fixture: advertises `loadSession` and, when replaying a session on
`session/load`, includes a `compaction_update` although the client never advertised
`clientCapabilities.session.compaction` -- the capability is required for replay as well as live
delivery. Nothing is sent live, so this proves the replay path is checked. Violates
ACP-CLIENTCAP-005 only; the ACP-LOAD-* requirements still PASS.
"""

import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).parent))

from _base import ConformingAgent  # noqa: E402

CAPABILITIES = {"loadSession": True}


class ReplaysCompactionAgent(ConformingAgent):
    def _handle_load(self, msg_id: Any, params: dict[str, Any]) -> None:
        compaction = {"sessionUpdate": "compaction_update", "compactionId": "cmp-1", "status": "completed"}
        self._notify("session/update", {"sessionId": params.get("sessionId"), "update": compaction})
        super()._handle_load(msg_id, params)


def main() -> None:
    ReplaysCompactionAgent(
        capabilities=CAPABILITIES, agent_name="tck-fixture-replays-compaction-unadvertised"
    ).run()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Positive control: asks for permission with an option whose `kind` is a `_`-prefixed custom
value (`"_tck_custom_kind"`) -- legal per the open-enum extensibility rule. Must PASS
`ACP-ENUM-201`. Paired with `unprefixed_custom_permission_kind.py`.
"""

import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).parent))

from _base import AsksPermissionAgent  # noqa: E402


class PrefixedCustomPermissionKindAgent(AsksPermissionAgent):
    def _permission_options(self) -> list[dict[str, Any]]:
        return [
            {"optionId": "allow-once", "name": "Allow", "kind": "allow_once"},
            {"optionId": "cast-spell", "name": "Cast a spell", "kind": "_tck_custom_kind"},
        ]


def main() -> None:
    PrefixedCustomPermissionKindAgent(capabilities={"session": {}}).run()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Non-conforming fixture: when the client advertises `clientCapabilities.auth.terminal`, it
advertises a `type: "terminal"` auth method whose `args` is a string instead of an array of
strings. Violates ACP-AUTH-006 only; without the capability it advertises no terminal method,
so ACP-AUTH-002 still PASSes.
"""

import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).parent))

from _base import ConformingAgent  # noqa: E402


class TerminalAuthBadShapeAgent(ConformingAgent):
    def _initialize_result(self) -> dict[str, Any]:
        result = super()._initialize_result()
        auth = self._client_capabilities.get("auth")
        if isinstance(auth, dict) and auth.get("terminal") is True:
            result["authMethods"] = [
                {"type": "terminal", "id": "tck-terminal", "name": "Terminal", "args": "--login"}
            ]
        return result


def main() -> None:
    TerminalAuthBadShapeAgent().run()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Non-conforming fixture: rejects unsupported versions with the right `-32022` code, but its
`data` omits the required `supported` array (initialization.mdx:100). FAILs exactly
`ACP-INIT-205`.
"""

import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).parent))

from _base import ConformingAgent  # noqa: E402


class UnsupportedVersionBadDataAgent(ConformingAgent):
    def _reject_unsupported_version(self, msg_id: Any, requested: int) -> None:
        self._init_rejected = True
        self._write(
            {
                "jsonrpc": "2.0",
                "id": msg_id,
                "error": {
                    "code": -32022,
                    "message": "Unsupported protocol version",
                    "data": {"requested": requested},
                },
            }
        )


def main() -> None:
    UnsupportedVersionBadDataAgent(capabilities={"session": {}}).run()


if __name__ == "__main__":
    main()
